def header(active='',prefix=''):
 nav=''.join(f'<a class="{"current" if active==p else ""}" href="{prefix}{p}">{n}</a>' for n,p in [('Home','index.html'),('About Us','about.html'),('Services','services.html'),('Insights','insights.html'),('Contact','contact.html')])
