 if slug=='bookkeeping':
  return '''<div class="editorial-art art-books"><span class="art-small">BOOKKEEPING / ROUTINES</span><strong>The Simple Side<br>Of Staying Organised.</strong><div class="art-ledger"><div><i></i><span>Keep records together</span><b>✓</b></div><div><i></i><span>Review transactions</span><b>✓</b></div><div><i></i><span>Stay on top of accounts</span><b>✓</b></div></div></div>'''
