# CUSTOMER PORTAL LINK INTEGRATION (Phase 2): idempotent after static regeneration.
from pathlib import Path as _PortalPath
import re as _portal_re
def _add_portal_link(_s, _pre):
    if 'portal-nav-link' not in _s:
        _link=f'<a class="portal-nav-link" href="{_pre}client-login.html">Client Portal <span aria-hidden="true">↗</span></a>'
        _s=_portal_re.sub(r'(<a class="header-contact")', lambda _m:_link+_m.group(1), _s, count=1)
    _foot=f'<a href="{_pre}client-login.html">Client Portal</a>'
    if _foot not in _s:
        _s=_portal_re.sub(r'(<div><h4>Explore</h4><div class="footer-links">.*?<a href="'+_portal_re.escape(_pre)+r'contact.html">Contact</a>)',lambda _m:_m.group(1)+_foot,_s,count=1,flags=_portal_re.S)
    if _foot not in _s:
        _s=_portal_re.sub(r'(<div><h4>Explore</h4>.*?<a href="'+_portal_re.escape(_pre)+r'contact.html">Contact Us</a>)',lambda _m:_m.group(1)+_foot,_s,count=1,flags=_portal_re.S)
    return _s.replace('There are no login accounts, customer dashboards or databases in this preview.','The customer portal is a design-only demonstration without real login accounts, customer records or a database.')
for _page in _PortalPath(__file__).resolve().parent.rglob('*.html'):
    if _page.name in {'client-login.html','client-portal.html'}: continue
    _prefix='../' if _page.parent.name=='insights' else ''
    _existing=_page.read_text(encoding='utf-8')
    _adjusted=_add_portal_link(_existing,_prefix)
    if _existing!=_adjusted: _page.write_text(_adjusted,encoding='utf-8')
